'use strict';
colors.Bramble='#b98559';
bondDescriptions.Bramble='Level 2: +1 wild herb per pick';
creatureTemperaments.Bramble={trait:'Shy · listens to the orchard',clues:['It curls beneath a leaf. Sit quietly and let it come to you.','It uncurls, tapping a paw in time with the rustling leaves. A gentle hum might help.'],actions:[['still','Sit quietly'],['hum','Hum with the leaves'],['reach','Reach towards it']],best:['still','hum'],good:'It uncurls and shuffles a little closer.',bad:'It tucks its nose away. Give it time and listen.'};
const orchardTypes=['orchardJournal','orchardWell','orchardBed','orchardNest'];
const orchardNear=nearest;nearest=function(){let best=orchardNear(),d=best?Math.hypot(best.x-player.x,best.y-player.y):43;for(const o of map.objects.filter(o=>orchardTypes.includes(o.type))){const n=Math.hypot(o.x-player.x,o.y-player.y);if(n<d){best=o;d=n;}}return best;};
function orchardChapter(){return OrchardCore.chapters[state.orchard.stage];}
function orchardQuestCard(){const q=state.orchard,c=orchardChapter();return `<article class="story-feature">${gameIcon(q.stage===7?'check':'seed')}<small>BRAMBLE ORCHARD · ${Math.min(7,q.stage+1)} / 7</small><h3>${c?c[0]:'An orchard full of life'}</h3><p>${c?c[1]:'Bramble has a home, the nursery is thriving and the western marsh trail is open.'}</p>${q.stage===2?`<span>${Math.min(8,Math.max(0,state.frontier.gathered.herbs-q.herbStart))} / 8 fresh herbs</span>`:q.stage===4?`<span>${q.beds.length} / 3 beds watered · ${q.water} water remaining</span>`:''}</article>`;}
function orchardGuide(){panel('The orchard awakens',orchardQuestCard()+'<div class="actions"><button data-ui="close">Back to the trail</button><button data-front="requests">Regional requests</button></div>','Tessa’s story','orchard');}
function tessaDialog(){const q=state.orchard;const lines=['“This orchard once fed the whole valley. Will you help me hear it grow again?”','“My old notebook is beside the cottage steps. It holds the nursery plan.”','“Fresh herbs tell us whether the soil is healthy. Pick eight, then come back.”','“Take timber and herbs to the nursery across the stream. We’ll mend it together.”','“The frame is sound. Fill the can at the stone well and water all three beds.”','“Something small is watching the new leaves. Follow the southern path to the quiet clearing.”','“You found our little gardener! Let’s open the nursery—and the old marsh trail.”','“Listen. Bees, leaves, tiny paws. You brought the orchard back.”'];const action=q.stage===0?'talk':q.stage===2?'herbs':q.stage===6?'finish':null;panel('Tessa',`<canvas data-orchard-portrait="tessa" width="96" height="96" class="portrait" aria-label="Tessa the botanist"></canvas><p>${lines[q.stage]}</p>${orchardQuestCard()}<div class="actions">${action?`<button data-orchard="${action}" ${q.stage===2&&state.frontier.gathered.herbs-q.herbStart<8?'disabled':''}>${q.stage===0?'I’ll help':q.stage===2?'Show the fresh herbs':'Celebrate · collect rewards'}</button>`:''}<button data-front="requests">Requests</button><button data-ui="close">See you soon</button></div>`,'Orchard botanist','orchard');orchardPortraits();}
function orchardObjectMenu(o){const q=state.orchard;let title='The orchard',body='',action='';
 if(o.type==='orchardJournal'){title='A weathered notebook';body='“Good soil, sound timber, fresh water. Leave a quiet corner for our smallest neighbours.”';if(q.stage===1)action='<button data-orchard="journal">Take the nursery plan</button>';}
 if(o.type==='landmark'){title='The old nursery';body=q.stage<3?'Tessa has a plan for this place. Visit her cottage to the east.':q.stage===3?'Repair the nursery frame, then bring its growing beds back to life.':q.stage<7?'The frame is repaired. Follow Tessa’s plan to bring the orchard back.':'A living nursery. Your harvests now yield an extra crop.';if(q.stage===3)action=`${state.frontier.projects.nursery?'<p>Materials already paid for.</p>':`<div class="ingredient-row">${chip('wood',40,state.wood)}${chip('herbs',8,state.herbs)}</div>`}<button data-orchard="repair" ${!state.frontier.projects.nursery&&(state.wood<40||state.herbs<8)?'disabled':''}>Repair the frame</button>`;}
 if(o.type==='orchardWell'){title='The stone well';body=q.stage===4?'Fill the watering can here, then visit the three growing beds beside the nursery.':'Cool spring water for the orchard. Tessa will show you when the nursery is ready.';if(q.stage===4)action=`<div class="ingredient-row">${chip('fish',q.water)}<span>${q.water} / 3 water charges</span></div><button data-orchard="fill" ${q.water===3?'disabled':''}>${q.water===3?'Watering can full':'Fill watering can'}</button>`;}
 if(o.type==='orchardBed'){title='Nursery bed '+(o.bed+1);body=q.beds.includes(o.bed)?'Fresh leaves reach towards the glass. This bed is watered.':q.stage===4?'The soil is ready. Give these seedlings their first drink.':'Prepare the nursery with Tessa before tending this bed.';if(q.stage===4&&!q.beds.includes(o.bed))action=`<button data-orchard="water" data-bed="${o.bed}" ${q.water<1?'disabled':''}>Water seedlings</button>`;}
 if(o.type==='orchardNest'){if(q.stage>=5&&!state.team.includes('Bramble')){encounter={name:'Bramble',trust:0};encounterDialog();return;}title='The quiet clearing';body=state.team.includes('Bramble')?'Bramble’s leaf nest rests beneath the apples. A little home, always waiting.':'Tiny pawprints circle a nest of leaves. Perhaps a healthier orchard will bring its owner home.';}
 panel(title,`<p>${body}</p>${action}<div class="actions"><button data-orchard="guide">Tessa’s plan</button><button data-ui="close">Keep exploring</button></div>`,'Bramble Orchard','orchard');
}
const orchardInteract=interact;interact=function(){if(!dialog&&!activity){const o=nearest();if(SaveStore.status().blocked){saveMenu();return;}if(map.id==='tessa'&&o?.name==='Tessa'){tessaDialog();return;}if(map.id==='orchard'&&(orchardTypes.includes(o?.type)||o?.type==='landmark')){faceTarget(o);orchardObjectMenu(o);return;}}orchardInteract();};
app.addEventListener('click',e=>{const b=e.target.closest('[data-orchard]');if(!b||b.disabled)return;const a=b.dataset.orchard;if(a==='guide'){orchardGuide();return;}if(SaveStore.status().blocked){saveMenu();return;}const o=nearest(),allowed=['talk','herbs','finish'].includes(a)?map.id==='tessa'&&o?.name==='Tessa':map.id==='orchard'&&({journal:'orchardJournal',repair:'landmark',fill:'orchardWell',water:'orchardBed'}[a]===o?.type);if(!allowed||(a==='water'&&Number(b.dataset.bed)!==o.bed))return;if(OrchardCore.act(state,a,Number(b.dataset.bed))){finish(a==='finish'?'The orchard is thriving! +100 coins · +3 trail marks · +6 seeds':a==='fill'?'Watering can filled · 3 charges':a==='water'?`${state.orchard.beds.length} / 3 beds watered`:a==='repair'?'Nursery repaired! Time to water the seedlings.':'Tessa’s plan updated.');if(a==='water')bursts.push({x:o.x,y:o.y-12,t:1.5,label:'Watered',color:'#b7e5df'});}if(map.id==='tessa')tessaDialog();else orchardObjectMenu(o);});
const orchardTick=tickActivities;tickActivities=function(dt){const people=map.npcs;if(map.id==='tessa')map.npcs=[];orchardTick(dt);if(map.id==='tessa')map.npcs=people;if(OrchardCore.act(state,'friend')){state.jobs.Bramble='berries';finish('Bramble joined the orchard family. Tell Tessa the good news!');}};
const orchardComplete=completeActivity;completeActivity=function(){if(activity?.o.type==='herb'&&state.life.active==='Bramble'&&MossSystems.level(state,'Bramble')>=2)state.herbs++;orchardComplete();};
const orchardAdventure=adventureMenu;adventureMenu=function(){orchardAdventure();if(taskTab==='story'){const b=document.createElement('button');b.dataset.orchard='guide';b.textContent=state.orchard.stage===7?'Bramble Orchard · Complete':'Tessa’s orchard · '+orchardChapter()[0];document.querySelector('.dialog .panel-tabs').after(b);}};
const orchardMap=mapPanel;mapPanel=function(){orchardMap();const b=document.createElement('button');b.dataset.orchard='guide';b.textContent='Bramble Orchard · Tessa’s plan';document.querySelector('.dialog').append(b);};

// Old saves may stand where the new stream or cottage now is.
if(map.id==='orchard'&&blocked(map,player.x,player.y)){player.x=45*T+16;player.y=19*T+16;follower.x=player.x-24;follower.y=player.y;save();}
